import{_ as s,C as n,o as a,c as i,aj as e,G as r}from"./chunks/framework.BwH0p-pt.js";const m=JSON.parse('{"title":"Webhooks","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/configuration/webhooks.md","filePath":"2.0/configuration/webhooks.md","lastUpdated":1781079046000}'),h={name:"2.0/configuration/webhooks.md"};function d(l,t,g,c,u,p){const o=n("ImagePopup");return a(),i("div",null,[t[0]||(t[0]=e('<h1 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h1><p>Webhooks in <a href="https://unopim.com/" target="_blank" rel="noreferrer">UnoPim</a> let you push real-time product update notifications to an external URL whenever product data changes. Instead of polling the API, your connected systems (e-commerce storefronts, ERPs, marketplaces) receive an HTTP request the moment a product is created, updated, or deleted.</p><p>The Webhook Settings page is located at <strong>Configuration → Webhooks</strong> in the admin sidebar.</p><h2 id="general-tab" tabindex="-1">General Tab <a class="header-anchor" href="#general-tab" aria-label="Permalink to &quot;General Tab&quot;">​</a></h2><p>The <strong>General</strong> tab is where you enable the webhook and configure the destination URL. It uses a two-panel layout.</p>',5)),r(o,{src:"/assets/2.0/images/settings/webhook-settings.png",alt:"Webhook Settings"}),t[1]||(t[1]=e('<h3 id="enable-the-webhook-and-set-the-url" tabindex="-1">Enable the Webhook and Set the URL <a class="header-anchor" href="#enable-the-webhook-and-set-the-url" aria-label="Permalink to &quot;Enable the Webhook and Set the URL&quot;">​</a></h3><p><strong>Step 1:</strong> Navigate to <strong>Configuration → Webhooks</strong> in the admin sidebar. The <strong>General</strong> tab is selected by default.</p><p><strong>Step 2:</strong> In the <strong>General</strong> panel on the left, toggle <strong>Active Webhook</strong> to enable webhook delivery.</p><p><strong>Step 3:</strong> In the <strong>Settings</strong> panel on the right, enter your <strong>Webhook URL</strong> (e.g., <code>https://example.com/webhook</code>). This is the endpoint that will receive POST requests whenever product data changes.</p><p><strong>Step 4:</strong> Click the <strong>Save</strong> button at the top-right of the page to apply your configuration.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use a service like <a href="https://webhook.site" target="_blank" rel="noreferrer">webhook.site</a> during development to inspect the payloads UnoPim sends before building your processing logic.</p></div><h2 id="logs-tab" tabindex="-1">Logs Tab <a class="header-anchor" href="#logs-tab" aria-label="Permalink to &quot;Logs Tab&quot;">​</a></h2><p>The <strong>Logs</strong> tab displays a record of every webhook request that UnoPim has sent. Use it to monitor delivery status and troubleshoot failures.</p>',8)),r(o,{src:"/assets/2.0/images/settings/webhook-logs.png",alt:"Webhook Logs"}),t[2]||(t[2]=e('<p>The log datagrid includes the following columns:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Id</strong></td><td>Unique identifier for the log entry</td></tr><tr><td><strong>Date/Time</strong></td><td>When the webhook request was sent</td></tr><tr><td><strong>SKU</strong></td><td>The product SKU that triggered the webhook</td></tr><tr><td><strong>User</strong></td><td>The admin user whose action triggered the change</td></tr><tr><td><strong>Status</strong></td><td>The HTTP response status code returned by your endpoint</td></tr><tr><td><strong>Actions</strong></td><td>View details of the individual log entry</td></tr></tbody></table><p>You can use the <strong>search bar</strong> to search by code, the <strong>Filter</strong> button to narrow results, and the <strong>pagination</strong> controls to browse through entries.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you see non-200 status codes in the logs, check that your endpoint is reachable, returns a 200 OK response, and can handle the incoming JSON payload correctly.</p></div><h2 id="history-tab" tabindex="-1">History Tab <a class="header-anchor" href="#history-tab" aria-label="Permalink to &quot;History Tab&quot;">​</a></h2><p>The <strong>History</strong> tab tracks every change made to the webhook configuration itself. Use it to audit when settings were modified and by whom.</p>',6)),r(o,{src:"/assets/2.0/images/settings/webhook-history.png",alt:"Webhook History"}),t[3]||(t[3]=e('<p>The history datagrid includes the following columns:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Date/Time</strong></td><td>When the configuration change was made</td></tr><tr><td><strong>Version</strong></td><td>The version number of the configuration snapshot</td></tr><tr><td><strong>User</strong></td><td>The admin user who made the change</td></tr><tr><td><strong>Actions</strong></td><td>Click the eye icon to view the full details of what changed</td></tr></tbody></table><p>This is useful for tracking when the webhook URL was updated, when the webhook was enabled or disabled, and which user made the change.</p><h2 id="quick-setup-summary" tabindex="-1">Quick Setup Summary <a class="header-anchor" href="#quick-setup-summary" aria-label="Permalink to &quot;Quick Setup Summary&quot;">​</a></h2><ol><li>Go to <strong>Configuration → Webhooks</strong>.</li><li>On the <strong>General</strong> tab, toggle <strong>Active Webhook</strong> on.</li><li>Enter your <strong>Webhook URL</strong> in the Settings panel.</li><li>Click <strong>Save</strong>.</li><li>Switch to the <strong>Logs</strong> tab to monitor outgoing webhook deliveries and verify successful responses.</li><li>Switch to the <strong>History</strong> tab to review any past configuration changes.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If your receiving endpoint is temporarily down, toggle the Active Webhook off to pause deliveries. Your configuration is preserved and you can re-enable it at any time without re-entering the URL.</p></div>',6))])}const k=s(h,[["render",d]]);export{m as __pageData,k as default};
